{"claims":[{"claim_text":"The citizens of the District of Columbia are entitled to autonomy in their civic affairs, full political representation as Americans who are fully taxed, and statehood.", "claim_types":["policy_position"],"evidence_ids":[1]},{"claim_text":"Puerto Ricans have been U.S. Citizens since 1917, but the island's ultimate status has not been determined and its 3.9 million residents still do not have voting representation in their national government.", "claim_types":["factual_assertion"],"evidence_ids":[1]},{"claim_text":"The people of Puerto Rico are entitled to the permanent and fully democratic status of their choice.", "claim_types":["policy_position"],"evidence_ids":[1]},{"claim_text":"Democrats will continue to work in the White House and Congress to clarify the options for Puerto Rico and enable them to choose and to obtain such a status from among all realistic options.", "claim_types":["policy_position"],"evidence_ids":[1]},{"claim_text":"The people of Guam, American Samoa, and the Virgin Islands have a right to be fully self-governing.", "claim_types":["policy_position"],"evidence_ids":[1]},{"claim_text":"Democrats are committed to fair treatment in economic and social policies as well as improvement in federal-territorial relations in accordance with the needs of each area.", "claim_types":["policy_position"],"evidence_ids":[1]},{"claim_text":"Elected representatives of Guam, American Samoa, and the Virgin Islands will be regularly consulted on policies, laws, and treaties that affect the areas.", "claim_types":["policy_position"],"evidence_ids":[1]},{"claim_text":"Democrats will ensure fair treatment for U.S. Citizens in Guam, American Samoa, and the Virgin Islands.", "claim_types":["policy_position"],"evidence_ids":[1]}],"unresolved_references":[]}
